SELECT qprt_checks_pr.*, qprt_checks_pr.numw AS p, qprt_checks_pr.bdka, "משקפיים" & " " & nz([qprt_checks_pr]![ct]) AS q1
FROM qprt_checks_pr
WHERE (((qprt_checks_pr.numw)=Forms!customers!numw) And ((qprt_checks_pr.bdka)=True) And (("משקפיים" & " " & nz(qprt_checks_pr!ct))=Forms!person_orders_list!color)) Or (((qprt_checks_pr.numw)=Forms!customers!numw) And (("משקפיים" & " " & nz(qprt_checks_pr!ct))=Forms!person_orders_list!color2)) Or (((qprt_checks_pr.numw)=Forms!customers!numw) And (("משקפיים" & " " & nz(qprt_checks_pr!ct))=Forms!person_orders_list!color & " " & nz(qprt_checks_pr!ct))) Or (((qprt_checks_pr.numw)=Forms!customers!numw) And (("משקפיים" & " " & nz(qprt_checks_pr!ct))=Forms!person_orders_list!color2 & " " & nz(qprt_checks_pr!ct)));

