SELECT tb_ad_catalog.*, Val(nz([amount])) AS Expr1, Val(nz([amount_total])) AS Expr2, Val(nz([amount_total])) AS Expr3, "*" & [barcode] & "*" AS bordernum, SAPAKIM.[SHEM SAPAK]
FROM tb_ad_catalog LEFT JOIN SAPAKIM ON tb_ad_catalog.sapak=SAPAKIM.[CODE SAPAK]
WHERE (((Val(nz([amount])))>0) AND ((Val(nz([amount_total])))>0 And (Val(nz([amount_total])))<Val(nz([amount]))));

SELECT tb_catalog.*, tb_qnum.qnum, SAPAKIM.[SHEM SAPAK]
FROM (tb_catalog LEFT JOIN tb_qnum ON tb_catalog.wnum=tb_qnum.qnum) LEFT JOIN SAPAKIM ON tb_catalog.sapak=SAPAKIM.[CODE SAPAK]
WHERE (((tb_qnum.qnum) Is Null));

INSERT INTO tb_qnum ( qnum )
SELECT tb_qnum_un.qnum
FROM tb_qnum_un;

SELECT checks_prep.*, checks_prep.numw AS q1, checks_prep.CDate AS q2
FROM checks_prep
WHERE (((checks_prep.numw)=Forms!customers!numw) And ((checks_prep.CDate)<=Forms!person_orders_list!odate));

SELECT checks_prep_ad.*, checks_prep_ad.numw AS q1, checks_prep_ad.chdate AS q2
FROM checks_prep_ad
WHERE (((checks_prep_ad.numw)=Forms!customers!numw) And ((checks_prep_ad.chdate)<=Forms!person_orders_list!odate));

